// SQL versi dalam. Urutan ngikutin kurikulum SQLBolt dan Mode SQL Tutorial (SELECT → filter → urut → agregat → GROUP BY → HAVING → JOIN → LEFT JOIN → CASE → subquery → CTE → tanggal → window → studi kasus).
// Semua soal dicek pakai SQLite beneran di browser, database toko Belanjain. Teks ditulis sendiri.
;(() => {
  const { H, susun } = window.GAS_DALAM
  const { I, RK, P, Q, QB, L, T } = H
  const C = (judul, soal, langkah, o = {}) => H.C(judul, soal, langkah, { jenis: 'sql', ...o })
  const TABEL = '<table class="tabel-mini"><tr><th>tabel</th><th>isinya</th><th>kolom</th></tr><tr><td><code>pelanggan</code></td><td>30 pelanggan</td><td>id, nama, kota, segmen, tgl_daftar</td></tr><tr><td><code>produk</code></td><td>20 produk</td><td>id, nama, kategori, harga</td></tr><tr><td><code>pesanan</code></td><td>80 pesanan</td><td>id, pelanggan_id, tgl, status</td></tr><tr><td><code>item</code></td><td>isi tiap pesanan</td><td>pesanan_id, produk_id, qty</td></tr></table>'

  const pelajaran = [
    // ================= DASAR =================
    L('select', 'dasar', 'SELECT: ngambil kolom dari tabel', 9, [
      I('Database itu kumpulan tabel', `<p>Bayangin file Excel dengan beberapa sheet. Tiap sheet itu satu <b>tabel</b>, tiap baris satu data (satu pelanggan, satu pesanan), tiap kolom satu keterangan (nama, kota).</p><p>Sepanjang course ini kamu pakai database toko online <b>Belanjain</b>:</p>${TABEL}<p class="tip">Di tiap soal SQL ada tombol nama tabel. Ketuk buat ngintip 5 baris pertamanya.</p>`),
      I('Kalimat pertama: SELECT … FROM …', '<pre>SELECT nama, kota\nFROM pelanggan</pre><p>Dibaca: <i>"ambil kolom nama dan kota, dari tabel pelanggan"</i>.</p><ul><li><code>SELECT</code> milih <b>kolom</b>. Pisahin pakai koma. Urutan kolom di hasil ngikutin urutan yang kamu tulis.</li><li><code>*</code> artinya semua kolom.</li><li><code>AS</code> ganti judul kolom di hasil, misal <code>nama AS pelanggan</code>. Datanya ga berubah.</li><li><code>DISTINCT</code> buang baris yang dobel, misal <code>SELECT DISTINCT kota</code>.</li></ul><p>Kata kunci (SELECT, FROM) boleh huruf kecil, tapi biasain kapital biar gampang dibaca.</p>'),
      C('Daftar nama dan kota pelanggan', 'Tim marketing minta daftar nama pelanggan beserta kotanya.', [
        ['SELECT *\nFROM pelanggan', 'Kenalan dulu sama datanya. <code>*</code> ngambil semua kolom. Ada 30 baris dan 5 kolom.'],
        ['SELECT nama, kota\nFROM pelanggan', 'Ganti <code>*</code> sama kolom yang diminta aja. Barisnya tetap 30, kolomnya tinggal 2. <b>SELECT ga pernah ngurangin baris</b>, cuma milih kolom.'],
        ['SELECT nama AS pelanggan, kota\nFROM pelanggan', 'Biar judulnya enak dibaca di laporan, kasih alias pakai <code>AS</code>.'],
      ], { penutup: 'Pola mikirnya: tanya dulu "kolom apa aja yang diminta?" terus tulis di SELECT. Tabelnya di FROM.' }),
      C('Kota apa aja yang ada pelanggannya?', 'Pengen tau daftar kota tanpa ada yang dobel.', [
        ['SELECT kota\nFROM pelanggan', 'Kalau cuma SELECT kota, hasilnya 30 baris. Bandung muncul berkali-kali karena ada banyak pelanggan Bandung.'],
        ['SELECT DISTINCT kota\nFROM pelanggan', '<code>DISTINCT</code> nyisain satu baris buat tiap nilai yang beda. Sekarang tiap kota cuma muncul sekali.'],
      ]),
      QB('Lengkapin query buat nampilin <b>nama</b> dan <b>harga</b> semua produk.', 'SELECT ___, ___\nFROM produk', 'SELECT nama, harga FROM produk', 'Ganti tiap ___ pakai nama kolom. Kolom tabel produk: id, nama, kategori, harga.', { umum: ['Nyisain tanda ___ di query. Semua ___ harus diganti.'] }),
      Q('Tampilkan <b>semua kolom</b> dari tabel <code>pesanan</code>.', 'SELECT * FROM pesanan', 'SELECT * FROM nama_tabel', { umum: ['Nulis <code>SELECT pesanan</code> tanpa FROM. Setelah SELECT itu nama kolom, nama tabelnya setelah FROM.'] }),
      Q('Tampilkan <b>nama</b>, <b>kategori</b>, dan <b>harga</b> dari tabel <code>produk</code>.', 'SELECT nama, kategori, harga FROM produk', 'Tiga kolom, dipisah koma.', { umum: ['Lupa koma: <code>SELECT nama kategori</code> dibaca SQL sebagai kolom nama yang dikasih judul "kategori". Hasilnya cuma 1 kolom.', 'Koma kelebihan sebelum FROM: <code>SELECT nama, harga, FROM</code> bikin error.'] }),
      Q('Tampilkan daftar <b>segmen</b> pelanggan yang ada, <b>tanpa dobel</b>.', 'SELECT DISTINCT segmen FROM pelanggan', 'Pakai DISTINCT sebelum nama kolom.', { umum: ['Nulis <code>DISTINCT</code> setelah kolom. Posisinya harus langsung setelah SELECT.'] }),
      P('<code>SELECT harga FROM produk</code> hasilnya?', [['Satu kolom harga, semua 20 baris', 'SELECT cuma milih kolom. Barisnya tetap semua.'], ['Cuma produk termahal', 'Buat itu butuh ORDER BY dan LIMIT, atau MAX. Nanti dipelajari.'], ['Semua kolom produk', 'Semua kolom itu pakai *.'], ['Error karena kurang *', '* cuma salah satu pilihan. Nulis nama kolom langsung juga sah.']], 'SELECT itu nyaring vertikal (kolom). Nyaring horizontal (baris) itu tugas WHERE, pelajaran berikutnya.'),
      RK('Kartu contekan SELECT', [['SELECT a, b FROM t', 'ambil kolom a dan b dari tabel t'], ['SELECT * FROM t', 'semua kolom'], ['kolom AS judul', 'ganti judul kolom di hasil'], ['SELECT DISTINCT a', 'buang nilai a yang dobel'], ['Koma', 'pemisah antar kolom, jangan ada koma sebelum FROM']], 'SELECT milih kolom, ga ngurangin baris.'),
    ]),

    L('where', 'dasar', 'WHERE: nyaring baris', 10, [
      I('WHERE itu saringan', '<p>SELECT milih <b>kolom</b>. WHERE milih <b>baris</b>: cuma baris yang syaratnya benar yang lolos.</p><pre>SELECT nama, harga\nFROM produk\nWHERE harga > 100000</pre><table class="tabel-mini"><tr><th>tanda</th><th>arti</th><th>contoh</th></tr><tr><td><code>=</code></td><td>sama dengan</td><td><code>kota = \'Bandung\'</code></td></tr><tr><td><code>&lt;&gt;</code></td><td>tidak sama</td><td><code>status &lt;&gt; \'batal\'</code></td></tr><tr><td><code>&gt; &lt;</code></td><td>lebih dari, kurang dari</td><td><code>harga &lt; 50000</code></td></tr><tr><td><code>&gt;= &lt;=</code></td><td>minimal, maksimal</td><td><code>qty &gt;= 2</code></td></tr></table><ul><li>Teks pakai <b>kutip satu</b> dan peka huruf besar kecil: <code>\'Bandung\'</code> ≠ <code>\'bandung\'</code>.</li><li>Angka ditulis polos, tanpa kutip dan tanpa titik ribuan: <code>200000</code>, bukan <code>200.000</code>.</li></ul>'),
      I('Gabung syarat: AND, OR, IN', '<ul><li><code>AND</code>: dua syarat harus benar semua. Saringan makin ketat, baris makin sedikit.</li><li><code>OR</code>: cukup salah satu benar. Saringan makin longgar.</li><li><code>IN (\'a\', \'b\')</code>: singkatan dari beberapa OR di kolom yang sama.</li></ul><pre>WHERE kota IN (\'Jakarta\', \'Medan\')\n  AND segmen = \'Reguler\'</pre><p class="tip">Kalau nyampur AND dan OR, SQL ngerjain AND duluan. Pakai kurung biar maksudnya jelas: <code>WHERE (kota = \'Jakarta\' OR kota = \'Medan\') AND segmen = \'Reguler\'</code>.</p>'),
      C('Nyari pelanggan VIP di Bandung', 'Tim CRM mau ngirim hadiah ke pelanggan <b>VIP</b> yang tinggal di <b>Bandung</b>.', [
        ['SELECT nama, kota, segmen\nFROM pelanggan', 'Tentuin kolomnya dulu. Belum disaring, masih 30 baris.'],
        ["SELECT nama, kota, segmen\nFROM pelanggan\nWHERE kota = 'Bandung'", 'Saringan pertama: kota harus Bandung. Barisnya turun jadi 10. Perhatiin kutip satu dan huruf B kapital.'],
        ["SELECT nama, kota, segmen\nFROM pelanggan\nWHERE kota = 'Bandung'\n  AND segmen = 'VIP'", 'Tambah syarat kedua pakai <code>AND</code>. Sekarang tiap baris harus lolos dua-duanya. Tinggal 3 orang.'],
      ], { penutup: 'Tambah syarat satu-satu sambil liat jumlah barisnya. Kalau tiba-tiba 0 baris, biasanya salah huruf besar kecil atau salah nilai.' }),
      QB('Lengkapin: produk kategori <b>Elektronik</b> yang harganya <b>di bawah 300000</b>.', "SELECT nama, harga\nFROM produk\nWHERE kategori = ___\n  AND harga ___ 300000", "SELECT nama, harga FROM produk WHERE kategori = 'Elektronik' AND harga < 300000", "Teks pakai kutip satu: 'Elektronik'. Di bawah = tanda <."),
      Q('Tampilkan <code>nama</code> pelanggan yang tinggal di <b>Bandung</b>.', "SELECT nama FROM pelanggan WHERE kota = 'Bandung'", "WHERE kota = 'Bandung'", { umum: ["Lupa kutip: <code>WHERE kota = Bandung</code> bikin SQL nyari kolom bernama Bandung.", "Huruf kecil: <code>'bandung'</code> ga ketemu apa-apa karena datanya ditulis <code>'Bandung'</code>."] }),
      Q('Tampilkan <code>nama</code> dan <code>harga</code> produk yang harganya <b>lebih dari 200000</b>.', 'SELECT nama, harga FROM produk WHERE harga > 200000', 'Angka ditulis tanpa titik.', { umum: ['Nulis <code>200.000</code>. Di SQL titik itu desimal, jadi dibaca dua ratus koma nol.', 'Pakai <code>&gt;=</code>. Soal bilang "lebih dari", jadi 200000 pas ga ikut.'] }),
      Q('Tampilkan semua kolom pesanan yang statusnya <b>batal</b> atau <b>retur</b>.', "SELECT * FROM pesanan WHERE status IN ('batal','retur')", "status IN ('batal','retur'), atau dua syarat digabung OR.", { umum: ["Pakai AND: <code>status = 'batal' AND status = 'retur'</code> ga mungkin benar, satu pesanan cuma punya satu status. Hasilnya 0 baris."] }),
      Q('Tampilkan <code>nama</code> dan <code>kota</code> pelanggan segmen <b>Reguler</b> yang tinggal di <b>Jakarta atau Medan</b>.', "SELECT nama, kota FROM pelanggan WHERE kota IN ('Jakarta','Medan') AND segmen = 'Reguler'", "Kota pakai IN, segmen pakai AND.", { umum: ["Tanpa kurung: <code>kota = 'Jakarta' OR kota = 'Medan' AND segmen = 'Reguler'</code>. AND dikerjain duluan, jadi semua pelanggan Jakarta ikut walau bukan Reguler."] }),
      P("<code>WHERE kota = 'Jakarta' OR kota = 'Medan' AND segmen = 'VIP'</code> ngambil siapa?", [['Semua pelanggan Jakarta, plus pelanggan Medan yang VIP', 'AND diikat duluan: (Medan AND VIP), terus di-OR sama Jakarta.'], ['Pelanggan VIP di Jakarta atau Medan', 'Itu maksud yang biasanya diinginkan, tapi butuh kurung di sekitar OR.'], ['Cuma pelanggan VIP', 'Pelanggan Jakarta yang bukan VIP juga ikut.'], ['Error', 'Query-nya sah, cuma maknanya beda dari yang dikira.']], 'Aturan: AND dikerjain sebelum OR, mirip kali sebelum tambah di matematika. Pakai kurung biar aman.'),
      RK('Kartu contekan WHERE', [["WHERE kota = 'Bandung'", 'teks pakai kutip satu, peka huruf besar kecil'], ['WHERE harga > 100000', 'angka polos tanpa titik'], ['AND', 'semua syarat harus benar (makin ketat)'], ['OR', 'salah satu cukup (makin longgar)'], ["IN ('a','b')", 'salah satu dari daftar'], ['( … )', 'pakai kurung kalau nyampur AND dan OR']]),
    ]),

    L('filter', 'dasar', 'LIKE, BETWEEN, NOT: saringan yang lebih pinter', 9, [
      I('Nyari pola dan rentang', '<ul><li><code>LIKE</code> nyari pola teks. <code>%</code> = huruf apa aja, berapa pun jumlahnya. <code>_</code> = tepat satu huruf.<br><code>nama LIKE \'Kopi%\'</code> diawali Kopi, <code>LIKE \'%Katun%\'</code> mengandung Katun, <code>LIKE \'%L\'</code> diakhiri L.</li><li><code>BETWEEN a AND b</code> = rentang, <b>dua ujungnya ikut</b>. Sama aja kayak <code>&gt;= a AND &lt;= b</code>. Bisa buat angka dan tanggal.</li><li><code>NOT</code> ngebalik syarat: <code>NOT IN</code>, <code>NOT LIKE</code>, atau pakai <code>&lt;&gt;</code>.</li></ul>'),
      I('Tanggal dan nilai kosong', '<p>Tanggal di database ini ditulis teks <code>\'2026-03-15\'</code> (tahun-bulan-tanggal). Format ini bisa langsung dibandingin dan diurutin: <code>tgl BETWEEN \'2026-03-01\' AND \'2026-03-31\'</code>.</p><p><b>NULL</b> artinya kosong, ga ada isinya. Beda dari 0 atau teks kosong. Ngeceknya <b>wajib</b> pakai <code>IS NULL</code> atau <code>IS NOT NULL</code>. <code>= NULL</code> ga pernah benar.</p>'),
      C('Produk harga menengah di luar kategori Makanan', 'Tim promo nyari produk harga <b>50 ribu sampai 100 ribu</b>, tapi <b>bukan Makanan</b>.', [
        ['SELECT nama, kategori, harga\nFROM produk\nWHERE harga BETWEEN 50000 AND 100000', 'BETWEEN ngambil harga dari 50000 sampai 100000, ujungnya ikut. Ada 5 produk.'],
        ["SELECT nama, kategori, harga\nFROM produk\nWHERE harga BETWEEN 50000 AND 100000\n  AND kategori <> 'Makanan'", '<code>&lt;&gt;</code> buang yang kategorinya Makanan. Kopi Gayo (Makanan) hilang dari hasil.'],
        ["SELECT nama, kategori, harga\nFROM produk\nWHERE nama LIKE '%Katun%'", 'Contoh lain: nyari nama yang <b>mengandung</b> kata Katun. Dua tanda % artinya boleh ada teks apa aja di depan dan belakangnya.'],
      ]),
      QB('Lengkapin: pelanggan yang namanya <b>diawali Fajar</b>.', "SELECT nama, kota\nFROM pelanggan\nWHERE nama LIKE ___", "SELECT nama, kota FROM pelanggan WHERE nama LIKE 'Fajar%'", "Diawali = teksnya dulu, baru % di belakang. Jangan lupa kutip satu."),
      Q('Tampilkan semua kolom pesanan yang tanggalnya di bulan <b>Maret 2026</b> (1 sampai 31 Maret).', "SELECT * FROM pesanan WHERE tgl BETWEEN '2026-03-01' AND '2026-03-31'", "tgl BETWEEN '2026-03-01' AND '2026-03-31'", { umum: ["Nulis tanggal tanpa kutip: <code>2026-03-01</code> dibaca SQL sebagai pengurangan 2026 − 3 − 1.", "Format beda: <code>'01-03-2026'</code> ga cocok sama data yang formatnya tahun-bulan-tanggal."] }),
      Q('Tampilkan <code>nama</code> dan <code>harga</code> produk yang namanya <b>mengandung kata "Katun"</b>.', "SELECT nama, harga FROM produk WHERE nama LIKE '%Katun%'", "% di depan dan belakang.", { umum: ["Pakai <code>=</code>: <code>nama = '%Katun%'</code> nyari nama yang persis tulisannya %Katun%. Pola cuma jalan pakai LIKE."] }),
      Q('Tampilkan <code>id</code> dan <code>status</code> pesanan yang statusnya <b>bukan selesai</b>.', "SELECT id, status FROM pesanan WHERE status <> 'selesai'", "Pakai <> atau NOT IN.", { umum: ["Nulis <code>status != selesai</code> tanpa kutip. Teks tetap wajib dikutip."] }),
      P("<code>WHERE nama LIKE 'K%'</code> ngambil...", [['Nama yang diawali huruf K', '% di belakang = apa aja boleh setelah K.'], ['Nama yang mengandung K di mana aja', 'Itu butuh % di depan juga: \'%K%\'.'], ['Nama yang persis "K%"', 'Di LIKE, % itu wildcard, bukan huruf.'], ['Nama yang diakhiri K', 'Itu \'%K\'.']], 'Posisi % nentuin artinya.'),
      RK('Kartu contekan saringan', [["LIKE 'Kopi%'", 'diawali Kopi'], ["LIKE '%Katun%'", 'mengandung Katun'], ['BETWEEN 50000 AND 100000', 'rentang, ujungnya ikut'], ["<> 'selesai'", 'bukan selesai'], ["NOT IN ('a','b')", 'bukan salah satu dari daftar'], ['IS NULL', 'kosong (jangan pakai = NULL)']]),
    ]),

    L('order', 'dasar', 'ORDER BY dan LIMIT: urutin dan ambil teratas', 8, [
      I('Urutin hasil', '<pre>SELECT nama, harga\nFROM produk\nORDER BY harga DESC\nLIMIT 3</pre><ul><li><code>ORDER BY kolom</code> ngurutin hasil. Defaultnya <code>ASC</code> (kecil ke besar, A ke Z, tanggal lama ke baru). <code>DESC</code> kebalikannya.</li><li>Bisa beberapa kolom: <code>ORDER BY kota, nama</code> = urut kota dulu, terus di dalam kota yang sama urut nama.</li><li><code>LIMIT n</code> ambil n baris pertama dari hasil yang udah diurutin.</li></ul><p class="tip">Pola <b>Top N</b> yang sering ditanya di tes: <code>ORDER BY … DESC LIMIT N</code>.</p>'),
      I('Urutan nulis klausa', '<p>Klausa SQL punya urutan tetap. Kalau ketuker, error:</p><pre>SELECT …\nFROM …\nWHERE …\nORDER BY …\nLIMIT …</pre><p>WHERE nyaring dulu, ORDER BY ngurutin sisanya, LIMIT motong paling akhir.</p>'),
      C('5 produk termahal di luar Elektronik', 'Buat banner promo, ambil 5 produk paling mahal yang <b>bukan Elektronik</b>.', [
        ['SELECT nama, kategori, harga\nFROM produk', 'Kolom dulu. 20 produk, urutannya masih acak sesuai data.'],
        ["SELECT nama, kategori, harga\nFROM produk\nWHERE kategori <> 'Elektronik'", 'Saring Elektronik keluar. Sisa 15 produk.'],
        ["SELECT nama, kategori, harga\nFROM produk\nWHERE kategori <> 'Elektronik'\nORDER BY harga DESC", 'Urutin dari yang termahal pakai DESC. Sepatu Lari jadi paling atas.'],
        ["SELECT nama, kategori, harga\nFROM produk\nWHERE kategori <> 'Elektronik'\nORDER BY harga DESC\nLIMIT 5", 'Potong 5 teratas. Ini jawaban akhirnya.'],
      ]),
      QB('Lengkapin: <b>3 produk termurah</b>.', 'SELECT nama, harga\nFROM produk\nORDER BY harga ___\nLIMIT ___', 'SELECT nama, harga FROM produk ORDER BY harga ASC LIMIT 3', 'Termurah = dari kecil ke besar (ASC).', { urut: true }),
      Q('Tampilkan <code>nama</code> dan <code>harga</code> <b>5 produk termurah</b>.', 'SELECT nama, harga FROM produk ORDER BY harga ASC LIMIT 5', 'ORDER BY harga, LIMIT 5.', { urut: true, umum: ['Lupa ORDER BY: LIMIT 5 doang ngambil 5 baris pertama sesuai urutan data, bukan yang termurah.'] }),
      Q('Tampilkan <code>nama</code> dan <code>tgl_daftar</code> <b>3 pelanggan yang paling baru daftar</b>.', 'SELECT nama, tgl_daftar FROM pelanggan ORDER BY tgl_daftar DESC LIMIT 3', 'Paling baru = tanggal terbesar = DESC.', { urut: true, umum: ['Pakai ASC: itu malah ngambil pelanggan paling lama.'] }),
      Q('Tampilkan <code>kota</code> dan <code>nama</code> semua pelanggan, urut <b>kota A sampai Z</b>, lalu <b>nama A sampai Z</b> di dalam kota yang sama.', 'SELECT kota, nama FROM pelanggan ORDER BY kota, nama', 'ORDER BY dua kolom dipisah koma.', { urut: true, umum: ['Nulis <code>ORDER BY kota ORDER BY nama</code>. ORDER BY cukup sekali, kolomnya dipisah koma.'] }),
      P('Mau 1 produk termahal. Query yang pas?', [['SELECT nama, harga FROM produk ORDER BY harga DESC LIMIT 1', 'Urut dari termahal, ambil 1.'], ['SELECT nama, harga FROM produk LIMIT 1', 'Tanpa ORDER BY, yang keluar baris pertama di data, belum tentu termahal.'], ['SELECT nama, harga FROM produk ORDER BY harga LIMIT 1', 'Default ASC, jadi ini yang termurah.'], ['SELECT TOP harga FROM produk', 'TOP itu sintaks SQL Server dan penulisannya juga salah. Di SQLite pakai LIMIT.']], 'Top 1 = ORDER BY DESC + LIMIT 1.'),
      RK('Kartu contekan urut', [['ORDER BY harga', 'kecil ke besar (ASC, default)'], ['ORDER BY harga DESC', 'besar ke kecil'], ['ORDER BY kota, nama', 'urut kota, lalu nama'], ['LIMIT 5', 'ambil 5 teratas'], ['Urutan', 'SELECT · FROM · WHERE · ORDER BY · LIMIT']]),
    ]),

    // ================= MENENGAH =================
    L('agregat', 'menengah', 'COUNT, SUM, AVG: ngeringkas jadi angka', 9, [
      I('Fungsi agregat', '<p>Fungsi agregat ngeringkas <b>banyak baris jadi satu angka</b>:</p><table class="tabel-mini"><tr><th>fungsi</th><th>arti</th></tr><tr><td><code>COUNT(*)</code></td><td>jumlah baris</td></tr><tr><td><code>COUNT(DISTINCT kota)</code></td><td>jumlah nilai yang beda</td></tr><tr><td><code>SUM(qty)</code></td><td>total</td></tr><tr><td><code>AVG(harga)</code></td><td>rata-rata</td></tr><tr><td><code>MIN</code> / <code>MAX</code></td><td>terkecil / terbesar</td></tr></table><p><code>ROUND(AVG(harga), 0)</code> bulatin hasilnya. Angka kedua = jumlah desimal.</p>'),
      I('WHERE dulu, baru dihitung', '<p>Kalau ada WHERE, barisnya disaring dulu, <b>baru</b> dihitung.</p><pre>SELECT COUNT(*) AS jumlah\nFROM pesanan\nWHERE status = \'selesai\'</pre><p>Dibaca: <i>"dari pesanan yang statusnya selesai, hitung ada berapa baris"</i>. Kasih nama hasilnya pakai AS biar laporan rapi.</p>'),
      C('Ringkasan produk Elektronik', 'Manajer kategori nanya: ada berapa produk Elektronik, termurah, termahal, dan rata-rata harganya berapa?', [
        ['SELECT COUNT(*) AS jumlah\nFROM produk', 'COUNT(*) ngitung semua baris tabel produk. 20 baris jadi satu angka.'],
        ["SELECT COUNT(*) AS jumlah\nFROM produk\nWHERE kategori = 'Elektronik'", 'Tambah WHERE. Disaring dulu jadi 5 baris Elektronik, baru dihitung.'],
        ["SELECT COUNT(*) AS jumlah,\n  MIN(harga) AS termurah,\n  MAX(harga) AS termahal,\n  ROUND(AVG(harga), 0) AS rata\nFROM produk\nWHERE kategori = 'Elektronik'", 'Beberapa agregat bisa sekaligus di satu SELECT, dipisah koma. Hasilnya tetap satu baris.'],
      ]),
      QB('Lengkapin: berapa banyak pesanan yang statusnya <b>selesai</b>?', "SELECT ___(*) AS jumlah\nFROM pesanan\nWHERE status = ___", "SELECT COUNT(*) AS jumlah FROM pesanan WHERE status = 'selesai'", 'Fungsi buat ngitung baris itu COUNT. Status ditulis pakai kutip satu.'),
      Q('Berapa <b>total qty</b> barang yang pernah dipesan? (tabel <code>item</code>)', 'SELECT SUM(qty) FROM item', 'Total = SUM.', { umum: ['Pakai COUNT(qty): itu ngitung ada berapa baris item, bukan total barangnya.'] }),
      Q('Berapa <b>rata-rata harga</b> produk kategori <b>Elektronik</b>? (ga usah dibulatin)', "SELECT AVG(harga) FROM produk WHERE kategori = 'Elektronik'", 'AVG + WHERE.', { umum: ['WHERE ditaruh sebelum SELECT. Urutan nulis tetap SELECT, FROM, WHERE.'] }),
      Q('Ada berapa <b>kota berbeda</b> di tabel pelanggan?', 'SELECT COUNT(DISTINCT kota) FROM pelanggan', 'COUNT(DISTINCT kolom).', { umum: ['COUNT(kota) ngasih 30 karena ngitung semua baris yang ada kotanya, termasuk yang dobel.'] }),
      P('Bedanya <code>COUNT(*)</code> dan <code>COUNT(DISTINCT pelanggan_id)</code> di tabel pesanan?', [['Yang pertama jumlah pesanan, yang kedua jumlah pelanggan yang pernah pesan', 'Satu pelanggan bisa punya banyak pesanan, jadi DISTINCT ngitung orangnya sekali.'], ['Sama aja', 'Beda kalau ada pelanggan yang pesan lebih dari sekali.'], ['Yang kedua selalu lebih besar', 'Kebalikannya. DISTINCT ga mungkin lebih besar dari jumlah baris.'], ['DISTINCT ga bisa dipakai di COUNT', 'Bisa, dan sering dipakai.']], 'Pertanyaan "berapa pesanan" beda sama "berapa pelanggan". Tes kerja suka ngejebak di sini.'),
      RK('Kartu contekan agregat', [['COUNT(*)', 'jumlah baris'], ['COUNT(DISTINCT a)', 'jumlah nilai a yang beda'], ['SUM(a) / AVG(a)', 'total / rata-rata'], ['MIN(a) / MAX(a)', 'terkecil / terbesar'], ['ROUND(x, 0)', 'bulatin'], ['WHERE', 'nyaring dulu, baru dihitung']]),
    ]),

    L('group', 'menengah', 'GROUP BY: ngitung per kelompok', 10, [
      I('Pivot table versi SQL', '<p>Agregat biasa ngasih satu angka buat semua baris. <code>GROUP BY</code> ngasih <b>satu angka per kelompok</b>, persis kayak PivotTable.</p><pre>SELECT kota, COUNT(*) AS jumlah\nFROM pelanggan\nGROUP BY kota</pre><p>Cara kerjanya: baris-baris yang kotanya sama dikumpulin jadi satu tumpukan, terus tiap tumpukan dihitung COUNT-nya.</p>'),
      I('Aturan emas GROUP BY', '<p>Tiap kolom di SELECT harus salah satu dari dua ini:</p><ol><li>ada di <code>GROUP BY</code> (kolom pengelompok), atau</li><li>dibungkus fungsi agregat (COUNT, SUM, AVG, MIN, MAX).</li></ol><p>Contoh salah: <code>SELECT kota, nama, COUNT(*) … GROUP BY kota</code>. Satu kota punya banyak nama, SQL bingung mau nampilin nama yang mana. Database lain langsung error, SQLite diam-diam ngambil nama acak.</p><p>Bisa juga kelompok bertingkat: <code>GROUP BY kota, segmen</code>.</p>'),
      C('Jumlah pelanggan per kota', 'Tim ekspansi nanya: kota mana yang pelanggannya paling banyak?', [
        ['SELECT kota\nFROM pelanggan', 'Liat dulu kolom kotanya. 30 baris, kotanya berulang.'],
        ['SELECT kota, COUNT(*) AS jumlah\nFROM pelanggan\nGROUP BY kota', 'GROUP BY kota bikin satu baris per kota. COUNT(*) dihitung per tumpukan kota.'],
        ['SELECT kota, COUNT(*) AS jumlah\nFROM pelanggan\nGROUP BY kota\nORDER BY jumlah DESC', 'Urutin pakai alias <code>jumlah</code>. Bandung paling atas dengan 10 pelanggan.'],
      ], { penutup: 'Kalimat "per X" atau "tiap X" di soal hampir selalu artinya GROUP BY X.' }),
      QB('Lengkapin: <b>jumlah produk di tiap kategori</b>.', 'SELECT kategori, COUNT(*) AS jumlah\nFROM produk\nGROUP BY ___', 'SELECT kategori, COUNT(*) AS jumlah FROM produk GROUP BY kategori', 'Kelompoknya per kategori.'),
      Q('Tampilkan <code>kategori</code> dan <b>harga termahal</b> di tiap kategori.', 'SELECT kategori, MAX(harga) FROM produk GROUP BY kategori', 'MAX(harga) + GROUP BY kategori.', { umum: ['Lupa GROUP BY: hasilnya cuma satu baris, harga termahal dari semua produk.'] }),
      Q('Tampilkan <code>status</code> pesanan dan jumlahnya (<code>jumlah</code>), urut dari yang <b>paling banyak</b>. Kalau jumlahnya seri, urut status A sampai Z.', 'SELECT status, COUNT(*) AS jumlah FROM pesanan GROUP BY status ORDER BY jumlah DESC, status', 'GROUP BY status, terus ORDER BY jumlah DESC, status.', { urut: true, umum: ['ORDER BY ditaruh sebelum GROUP BY. Urutannya: GROUP BY dulu, baru ORDER BY.'] }),
      Q('Tampilkan <code>kota</code>, <code>segmen</code>, dan jumlah pelanggan untuk <b>tiap kombinasi kota dan segmen</b>.', 'SELECT kota, segmen, COUNT(*) FROM pelanggan GROUP BY kota, segmen', 'GROUP BY dua kolom.', { umum: ['GROUP BY cuma kota: segmen jadi kolom liar yang ga dikelompokin, angkanya salah.'] }),
      P('<code>SELECT kota, nama, COUNT(*) FROM pelanggan GROUP BY kota</code>. Masalahnya?', [['Kolom nama ga dikelompokin dan ga diagregat', 'Satu kota punya banyak nama. Hasil nama-nya ga bermakna.'], ['COUNT(*) ga boleh bareng GROUP BY', 'Justru itu pasangan paling umum.'], ['Harus pakai ORDER BY', 'ORDER BY opsional.'], ['Ga ada masalah', 'Di PostgreSQL/SQL Server ini langsung error.']], 'Aturan emas: kolom di SELECT = kolom GROUP BY atau agregat.'),
      RK('Kartu contekan GROUP BY', [['GROUP BY kota', 'satu baris per kota'], ['SELECT kota, COUNT(*)', 'kolom pengelompok + agregat'], ['GROUP BY kota, segmen', 'kelompok bertingkat'], ['ORDER BY jumlah DESC', 'alias boleh dipakai di ORDER BY'], ['"per X" / "tiap X"', 'tanda butuh GROUP BY X']]),
    ]),

    L('having', 'menengah', 'HAVING: nyaring setelah dikelompokkan', 9, [
      I('WHERE vs HAVING', '<p>Dua-duanya nyaring, tapi beda waktu:</p><ul><li><code>WHERE</code> nyaring <b>baris mentah</b>, sebelum dikelompokin.</li><li><code>HAVING</code> nyaring <b>kelompok</b>, setelah dihitung. Biasanya pakai agregat: <code>HAVING COUNT(*) &gt; 3</code>.</li></ul><p>WHERE ga bisa nyaring hasil COUNT karena pas WHERE jalan, hitungannya belum ada.</p>'),
      I('Urutan mesin ngerjain query', '<p>Ditulis mulai SELECT, tapi dikerjain dengan urutan ini:</p><pre>FROM      → ambil tabel\nWHERE     → saring baris\nGROUP BY  → kumpulin jadi kelompok\nHAVING    → saring kelompok\nSELECT    → pilih kolom dan hitung\nORDER BY  → urutin\nLIMIT     → potong</pre><p>Urutan ini jawaban buat banyak kebingungan, misalnya kenapa alias dari SELECT ga bisa dipakai di WHERE.</p>'),
      C('Kota dengan pelanggan Reguler lebih dari 2', 'Mau tau kota mana yang pelanggan <b>Reguler</b>-nya <b>lebih dari 2</b> orang.', [
        ['SELECT kota, COUNT(*) AS jumlah\nFROM pelanggan\nGROUP BY kota', 'Hitung semua pelanggan per kota dulu. Ini masih campur semua segmen.'],
        ["SELECT kota, COUNT(*) AS jumlah\nFROM pelanggan\nWHERE segmen = 'Reguler'\nGROUP BY kota", 'Saring barisnya dulu pakai <b>WHERE</b>: cuma pelanggan Reguler. Sekarang angkanya per kota khusus Reguler.'],
        ["SELECT kota, COUNT(*) AS jumlah\nFROM pelanggan\nWHERE segmen = 'Reguler'\nGROUP BY kota\nHAVING COUNT(*) > 2", 'Terakhir saring <b>kelompoknya</b> pakai HAVING: cuma kota yang hitungannya di atas 2. Tinggal Bandung dan Yogyakarta.'],
      ], { penutup: 'WHERE nentuin baris mana yang dihitung. HAVING nentuin hasil hitungan mana yang ditampilin.' }),
      QB('Lengkapin: kategori yang punya <b>minimal 4 produk</b>.', 'SELECT kategori, COUNT(*) AS jumlah\nFROM produk\nGROUP BY kategori\n___ COUNT(*) >= 4', 'SELECT kategori, COUNT(*) AS jumlah FROM produk GROUP BY kategori HAVING COUNT(*) >= 4', 'Nyaring hasil COUNT = HAVING.'),
      Q('Tampilkan <code>kota</code> dan jumlah pelanggannya, cuma kota yang pelanggannya <b>lebih dari 3</b>.', 'SELECT kota, COUNT(*) AS jumlah FROM pelanggan GROUP BY kota HAVING COUNT(*) > 3', 'GROUP BY kota HAVING COUNT(*) > 3', { umum: ['Pakai <code>WHERE COUNT(*) &gt; 3</code>: error "misuse of aggregate". Hasil hitungan cuma bisa disaring HAVING.'] }),
      Q('Tampilkan <code>kategori</code> dan rata-rata harganya, cuma kategori yang rata-ratanya <b>di atas 150000</b>.', 'SELECT kategori, AVG(harga) AS rata FROM produk GROUP BY kategori HAVING AVG(harga) > 150000', 'HAVING AVG(harga) > 150000', { umum: ['<code>WHERE harga &gt; 150000</code>: itu nyaring produknya dulu, jadi rata-ratanya dihitung dari produk mahal doang. Hasilnya beda.'] }),
      Q('Tampilkan <code>status</code> pesanan dan jumlahnya, cuma status yang jumlahnya <b>lebih dari 5</b>.', 'SELECT status, COUNT(*) FROM pesanan GROUP BY status HAVING COUNT(*) > 5', 'HAVING COUNT(*) > 5'),
      P('Mau ngitung pesanan per pelanggan, tapi <b>cuma pesanan selesai</b> yang dihitung. Syarat status ditaruh di?', [["WHERE status = 'selesai'", 'Status itu kolom baris mentah, jadi disaring sebelum dikelompokin.'], ["HAVING status = 'selesai'", 'HAVING buat nyaring hasil kelompok. Status bukan hasil hitungan.'], ['ORDER BY status', 'ORDER BY cuma ngurutin, ga nyaring.'], ['GROUP BY status', 'Itu malah bikin kelompok per status.']], 'Tanya: yang mau disaring itu baris asli (WHERE) atau angka hasil hitungan (HAVING)?'),
      RK('Kartu contekan HAVING', [['WHERE', 'saring baris, sebelum GROUP BY'], ['HAVING COUNT(*) > 3', 'saring kelompok, setelah dihitung'], ['Urutan jalan', 'FROM · WHERE · GROUP BY · HAVING · SELECT · ORDER BY · LIMIT'], ['Error "misuse of aggregate"', 'agregat ditaruh di WHERE, pindahin ke HAVING']]),
    ]),

    L('join', 'menengah', 'JOIN: nyambungin dua tabel', 11, [
      I('Kenapa datanya dipisah-pisah?', '<p>Tabel <code>pesanan</code> ga nyimpen nama pelanggan, cuma <code>pelanggan_id</code>. Kenapa? Biar kalau pelanggan ganti nama, cukup diubah di satu tempat. Ini namanya <b>normalisasi</b>.</p><p>Penghubungnya:</p><ul><li><b>Primary key</b>: kolom pengenal unik di tabelnya sendiri, misal <code>pelanggan.id</code>.</li><li><b>Foreign key</b>: kolom yang nunjuk ke primary key tabel lain, misal <code>pesanan.pelanggan_id</code>.</li></ul><pre>pelanggan.id  ←  pesanan.pelanggan_id\npesanan.id    ←  item.pesanan_id\nproduk.id     ←  item.produk_id</pre>'),
      I('Cara nulis JOIN', '<pre>SELECT p.id, c.nama, p.tgl\nFROM pesanan p\nJOIN pelanggan c ON c.id = p.pelanggan_id</pre><ul><li><code>pesanan p</code>: kasih alias pendek biar ga capek ngetik.</li><li><code>ON</code>: aturan pasangannya. Baris pesanan dipasangin sama baris pelanggan yang id-nya sama dengan pelanggan_id.</li><li>Kolom yang namanya sama di dua tabel (misal <code>id</code>, <code>nama</code>) wajib ditulis pakai alias: <code>c.nama</code>, <code>p.id</code>.</li></ul><p><code>JOIN</code> (atau INNER JOIN) cuma nyisain baris yang <b>punya pasangan</b> di dua tabel.</p>'),
      C('Pesanan lengkap dengan nama pelanggan', 'Tim CS butuh daftar pesanan dari pelanggan <b>Bandung</b>, lengkap sama nama pemesannya.', [
        ['SELECT id, pelanggan_id, tgl\nFROM pesanan', 'Tabel pesanan cuma punya pelanggan_id. Angka doang, ga ketauan siapa orangnya.'],
        ['SELECT p.id, p.tgl, c.nama, c.kota\nFROM pesanan p\nJOIN pelanggan c ON c.id = p.pelanggan_id', 'JOIN ke pelanggan. Tiap pesanan dicariin pelanggan yang id-nya cocok. Sekarang nama dan kota ikut muncul, 80 baris.'],
        ["SELECT p.id, p.tgl, c.nama, c.kota\nFROM pesanan p\nJOIN pelanggan c ON c.id = p.pelanggan_id\nWHERE c.kota = 'Bandung'", 'Setelah digabung, kolom dari tabel mana aja bisa dipakai di WHERE. Saring kota Bandung.'],
      ], { penutup: 'Cara mikir JOIN: data yang aku butuhin ada di tabel apa aja? Kolom apa yang nyambungin mereka? Tulis itu di ON.' }),
      QB('Lengkapin: tampilkan <b>nama produk</b> dan <b>qty</b> dari tiap baris item.', 'SELECT pr.nama, i.qty\nFROM item i\nJOIN produk pr ON pr.id = ___', 'SELECT pr.nama, i.qty FROM item i JOIN produk pr ON pr.id = i.produk_id', 'Kolom di item yang nunjuk ke produk itu produk_id. Tulis pakai alias i.'),
      Q('Tampilkan <code>id</code> pesanan, <code>nama</code> dan <code>kota</code> pelanggan untuk semua pesanan.', 'SELECT p.id, c.nama, c.kota FROM pesanan p JOIN pelanggan c ON c.id = p.pelanggan_id', 'FROM pesanan JOIN pelanggan ON pelanggan.id = pesanan.pelanggan_id', { umum: ['Nyambungin <code>c.id = p.id</code>: itu masangin pesanan nomor 5 sama pelanggan nomor 5, padahal ga ada hubungannya.', 'Nulis <code>id</code> tanpa alias: error "ambiguous column name" karena dua tabel punya kolom id.'] }),
      Q('Tampilkan <code>tgl</code> pesanan dan <code>nama</code> pelanggan untuk pesanan berstatus <b>batal</b>.', "SELECT p.tgl, c.nama FROM pesanan p JOIN pelanggan c ON c.id = p.pelanggan_id WHERE p.status = 'batal'", 'JOIN dulu, terus WHERE p.status.'),
      Q('Total omzet (qty × harga) tiap <b>kategori</b>, urut dari terbesar.', 'SELECT pr.kategori, SUM(i.qty * pr.harga) AS omzet FROM item i JOIN produk pr ON pr.id = i.produk_id GROUP BY pr.kategori ORDER BY omzet DESC', 'item JOIN produk, GROUP BY kategori, ORDER BY omzet DESC.', { urut: true, umum: ['SUM(pr.harga) doang: lupa dikali qty, jadi beli 3 barang dihitung 1.'] }),
      P('Fungsi bagian <code>ON c.id = p.pelanggan_id</code>?', [['Aturan buat masangin baris dua tabel', 'ON bilang kolom mana yang harus sama biar dua baris dianggap pasangan.'], ['Nyaring pesanan tertentu', 'Nyaring itu tugas WHERE.'], ['Ngurutin hasil', 'Itu ORDER BY.'], ['Bikin kolom baru', 'ON ga bikin kolom.']], 'JOIN tanpa ON yang bener = data kecampur ga karuan.'),
      RK('Kartu contekan JOIN', [['FROM a JOIN b ON b.id = a.b_id', 'gabung baris yang cocok'], ['Alias (pesanan p)', 'singkatan nama tabel'], ['p.id, c.nama', 'tulis alias kalau nama kolom sama'], ['Primary key', 'id unik di tabel sendiri'], ['Foreign key', 'kolom yang nunjuk ke id tabel lain'], ['JOIN biasa', 'baris tanpa pasangan dibuang']]),
    ]),

    L('leftjoin', 'menengah', 'LEFT JOIN dan gabung tiga tabel', 11, [
      I('JOIN biasa vs LEFT JOIN', '<ul><li><code>JOIN</code>: cuma baris yang punya pasangan di dua tabel.</li><li><code>LEFT JOIN</code>: <b>semua</b> baris tabel kiri (yang di FROM) tetap ikut. Kalau ga ada pasangannya, kolom dari tabel kanan diisi <code>NULL</code>.</li></ul><p>Ini dipakai buat pertanyaan kayak <i>"pelanggan mana yang belum pernah belanja?"</i>: LEFT JOIN, terus cari yang pasangannya NULL.</p><pre>FROM pelanggan c\nLEFT JOIN pesanan p ON p.pelanggan_id = c.id\nWHERE p.id IS NULL</pre>'),
      I('Gabung tiga tabel', '<p>JOIN bisa disambung terus kayak rantai. Buat tau <i>siapa beli produk apa</i>, butuh tiga tabel:</p><pre>FROM item i\nJOIN pesanan p   ON p.id = i.pesanan_id\nJOIN pelanggan c ON c.id = p.pelanggan_id</pre><p>Tiap JOIN punya ON sendiri. Ikutin panah foreign key-nya satu-satu.</p><p class="tip">Pas pakai LEFT JOIN, hitung pakai <code>COUNT(p.id)</code>, bukan <code>COUNT(*)</code>. COUNT(*) ngitung baris kosong hasil LEFT JOIN sebagai 1.</p>'),
      C('Pelanggan yang belum pernah belanja', 'Tim marketing mau kirim voucher ke pelanggan yang udah daftar tapi <b>belum pernah pesan</b>.', [
        ['SELECT c.nama, p.id AS pesanan_id\nFROM pelanggan c\nJOIN pesanan p ON p.pelanggan_id = c.id', 'Pakai JOIN biasa: cuma pelanggan yang punya pesanan yang muncul. Yang belum pernah pesan hilang, padahal itu yang dicari.'],
        ['SELECT c.nama, p.id AS pesanan_id\nFROM pelanggan c\nLEFT JOIN pesanan p ON p.pelanggan_id = c.id', 'Ganti jadi LEFT JOIN. Semua pelanggan ikut. Yang belum pernah pesan punya pesanan_id NULL. Scroll tabelnya, cari yang NULL.'],
        ['SELECT c.nama, p.id AS pesanan_id\nFROM pelanggan c\nLEFT JOIN pesanan p ON p.pelanggan_id = c.id\nWHERE p.id IS NULL', 'Saring yang NULL aja. Ketemu 6 pelanggan yang belum pernah belanja.'],
      ]),
      QB('Lengkapin: <b>total qty</b> yang dibeli tiap pelanggan. Butuh tiga tabel.', 'SELECT c.nama, SUM(i.qty) AS total_qty\nFROM item i\nJOIN pesanan p ON p.id = i.pesanan_id\nJOIN pelanggan c ON c.id = ___\nGROUP BY c.id, c.nama', 'SELECT c.nama, SUM(i.qty) AS total_qty FROM item i JOIN pesanan p ON p.id = i.pesanan_id JOIN pelanggan c ON c.id = p.pelanggan_id GROUP BY c.id, c.nama', 'Pelanggan nyambung ke pesanan lewat p.pelanggan_id. GROUP BY pakai c.id juga karena ada nama yang kembar.'),
      Q('Tampilkan <code>nama</code> pelanggan yang <b>belum pernah pesan</b>, pakai LEFT JOIN.', 'SELECT c.nama FROM pelanggan c LEFT JOIN pesanan p ON p.pelanggan_id = c.id WHERE p.id IS NULL', 'LEFT JOIN, lalu WHERE pesanan.id IS NULL.', { umum: ['Pakai <code>= NULL</code>: ga pernah benar. Wajib IS NULL.', 'Pakai JOIN biasa: pelanggan tanpa pesanan udah kebuang sebelum WHERE jalan, hasilnya 0 baris.'] }),
      Q('Tampilkan <code>nama</code> tiap pelanggan dan <b>jumlah pesanannya</b>, termasuk yang 0. Grup pakai <code>c.id, c.nama</code>.', 'SELECT c.nama, COUNT(p.id) AS jumlah FROM pelanggan c LEFT JOIN pesanan p ON p.pelanggan_id = c.id GROUP BY c.id, c.nama', 'LEFT JOIN + COUNT(p.id).', { umum: ['COUNT(*) ngasih 1 buat pelanggan yang belum pernah pesan, karena baris NULL-nya tetap kehitung satu baris. COUNT(p.id) ngelewatin NULL.'] }),
      Q('Tampilkan <code>nama</code> produk dan <b>total qty terjualnya</b>, urut dari yang paling laku.', 'SELECT pr.nama, SUM(i.qty) AS terjual FROM produk pr JOIN item i ON i.produk_id = pr.id GROUP BY pr.id, pr.nama ORDER BY terjual DESC, pr.nama', 'produk JOIN item, GROUP BY produk, ORDER BY terjual DESC. Kalau seri, urut nama.', { urut: true }),
      P('LEFT JOIN pelanggan ke pesanan. Pelanggan yang belum pernah pesan muncul dengan kolom pesanan berisi...', [['NULL', 'Ga ada pasangan, jadi kolom dari tabel kanan kosong.'], ['0', 'NULL beda dari 0. 0 itu angka.'], ['Data pesanan orang lain', 'LEFT JOIN ga pernah ngarang pasangan.'], ['Barisnya dihapus', 'Itu perilaku JOIN biasa.']], 'NULL = "ga ada data", dicek pakai IS NULL.'),
      RK('Kartu contekan LEFT JOIN', [['LEFT JOIN', 'semua baris kiri ikut, yang ga cocok jadi NULL'], ['WHERE kanan.id IS NULL', 'cari yang ga punya pasangan'], ['COUNT(kanan.id)', 'hitung pasangan, NULL ga kehitung'], ['JOIN … JOIN …', 'rantai tiga tabel, tiap JOIN punya ON'], ['GROUP BY c.id, c.nama', 'id ikut biar nama kembar ga kegabung']]),
    ]),

    // ================= MAHIR =================
    L('casewhen', 'mahir', 'CASE WHEN: bikin kategori sendiri', 10, [
      I('IF-nya SQL', "<pre>CASE\n  WHEN harga >= 500000 THEN 'Premium'\n  WHEN harga >= 100000 THEN 'Menengah'\n  ELSE 'Hemat'\nEND AS kelas</pre><ul><li>Dicek dari atas ke bawah. <b>Syarat pertama yang benar</b> yang dipakai, sisanya dilewatin.</li><li><code>ELSE</code> buat semua yang ga kena syarat mana pun. Tanpa ELSE, hasilnya NULL.</li><li>Selalu ditutup <code>END</code>, terus kasih nama pakai AS.</li></ul>"),
      I('CASE di dalam SUM: pivot manual', "<p>Trik yang sering dipakai analis buat ngitung beberapa kategori dalam satu baris:</p><pre>SELECT kota,\n  SUM(CASE WHEN segmen = 'VIP' THEN 1 ELSE 0 END) AS vip,\n  COUNT(*) AS total\nFROM pelanggan\nGROUP BY kota</pre><p>Tiap baris VIP dikasih nilai 1, sisanya 0. Dijumlah = jumlah VIP per kota.</p>"),
      C('Kelas harga produk', 'Tim pricing mau tau sebaran produk per kelas harga: <b>Premium</b> (≥ 500 ribu), <b>Menengah</b> (≥ 100 ribu), sisanya <b>Hemat</b>.', [
        ['SELECT nama, harga\nFROM produk', 'Mulai dari nama dan harga.'],
        ["SELECT nama, harga,\n  CASE WHEN harga >= 500000 THEN 'Premium'\n       WHEN harga >= 100000 THEN 'Menengah'\n       ELSE 'Hemat' END AS kelas\nFROM produk", 'Tambah kolom kelas pakai CASE. Smartwatch 650 ribu lolos syarat pertama jadi Premium. Madu 120 ribu gagal syarat pertama, lolos kedua, jadi Menengah.'],
        ["SELECT CASE WHEN harga >= 500000 THEN 'Premium'\n       WHEN harga >= 100000 THEN 'Menengah'\n       ELSE 'Hemat' END AS kelas,\n  COUNT(*) AS jumlah\nFROM produk\nGROUP BY kelas", 'Sekarang kelompokin per kelas. Di SQLite, alias dari SELECT boleh dipakai di GROUP BY.'],
      ], { penutup: 'Kalau syaratnya bertingkat (≥ 500 ribu, ≥ 100 ribu), tulis dari yang paling ketat dulu. Kalau kebalik, semua produk mahal ketangkep syarat ≥ 100 ribu duluan.' }),
      QB('Lengkapin: kolom <b>kelas</b> "Premium" kalau harga di atas 300000, selain itu "Reguler".', "SELECT nama,\n  CASE WHEN harga ___ 300000 THEN 'Premium'\n       ELSE ___ END AS kelas\nFROM produk", "SELECT nama, CASE WHEN harga > 300000 THEN 'Premium' ELSE 'Reguler' END AS kelas FROM produk", "Di atas = >. Teks pakai kutip satu."),
      Q('Hitung <b>jumlah produk per kelas harga</b> (Premium ≥ 500000, Menengah ≥ 100000, sisanya Hemat).', "SELECT CASE WHEN harga >= 500000 THEN 'Premium' WHEN harga >= 100000 THEN 'Menengah' ELSE 'Hemat' END AS kelas, COUNT(*) FROM produk GROUP BY kelas", 'CASE di SELECT, GROUP BY aliasnya.', { umum: ['Urutan WHEN kebalik (≥ 100000 duluan): produk 650 ribu ikut jadi Menengah.'] }),
      Q("Per <code>kota</code>, hitung jumlah pelanggan <b>VIP</b> (kolom <code>vip</code>) dan <b>total pelanggan</b> (kolom <code>total</code>).", "SELECT kota, SUM(CASE WHEN segmen = 'VIP' THEN 1 ELSE 0 END) AS vip, COUNT(*) AS total FROM pelanggan GROUP BY kota", "SUM(CASE WHEN segmen = 'VIP' THEN 1 ELSE 0 END)", { umum: ["WHERE segmen = 'VIP': kolom total jadi ikut cuma ngitung VIP, dan kota tanpa VIP hilang."] }),
      P("CASE WHEN harga >= 100000 THEN 'Menengah' WHEN harga >= 500000 THEN 'Premium' ELSE 'Hemat' END. Produk 650000 jadi apa?", [["Menengah", "650000 ≥ 100000 udah benar di syarat pertama. Syarat kedua ga pernah dicek."], ["Premium", "Bakal Premium kalau syarat ≥ 500000 ditulis duluan."], ["Hemat", "ELSE cuma kalau semua syarat gagal."], ["Error", "Sintaksnya sah."]], 'CASE berhenti di syarat pertama yang benar.'),
      RK('Kartu contekan CASE', [["CASE WHEN … THEN … ELSE … END", 'kolom baru dari aturan'], ['Urutan WHEN', 'dari yang paling ketat'], ['ELSE', 'cadangan, tanpa ELSE hasilnya NULL'], ['SUM(CASE WHEN x THEN 1 ELSE 0 END)', 'ngitung yang memenuhi syarat'], ['GROUP BY alias', 'kelompokin hasil CASE']]),
    ]),

    L('subquery', 'mahir', 'Subquery: query di dalam query', 10, [
      I('Pertanyaan dua langkah', '<p>Kadang jawabannya butuh hasil query lain dulu. <i>"Produk yang harganya di atas rata-rata"</i>: rata-ratanya harus dihitung dulu.</p><pre>SELECT nama, harga\nFROM produk\nWHERE harga > (SELECT AVG(harga) FROM produk)</pre><p>Query di dalam kurung dikerjain duluan, hasilnya (satu angka) dipakai buat ngebandingin.</p>'),
      I('Tiga tempat subquery', '<ul><li><b>Satu nilai</b> di WHERE, dibandingin pakai <code>&gt;</code>, <code>=</code>, dll. Harus ngembaliin tepat satu angka.</li><li><b>Daftar</b> pakai <code>IN</code> / <code>NOT IN</code>: <code>WHERE id IN (SELECT pelanggan_id FROM pesanan WHERE status = \'batal\')</code>.</li><li><b>Tabel sementara</b> di FROM: <code>SELECT … FROM (SELECT …) AS t</code>.</li></ul>'),
      C('Produk di atas rata-rata harga', 'Tim merchandising nanya: produk mana aja yang harganya di atas rata-rata?', [
        ['SELECT AVG(harga)\nFROM produk', 'Langkah 1: cari rata-ratanya dulu. 183650.'],
        ['SELECT nama, harga\nFROM produk\nWHERE harga > 183650', 'Langkah 2: pakai angka itu buat nyaring. Jalan, tapi angkanya ditulis manual. Kalau harga produk berubah, query ini ketinggalan.'],
        ['SELECT nama, harga\nFROM produk\nWHERE harga > (SELECT AVG(harga) FROM produk)', 'Langkah 3: ganti angkanya pakai query langkah 1 dalam kurung. Sekarang selalu ngikutin data terbaru.'],
      ]),
      QB('Lengkapin: pelanggan yang <b>belum pernah pesan</b>, pakai subquery.', 'SELECT nama\nFROM pelanggan\nWHERE id ___ (SELECT pelanggan_id FROM pesanan)', 'SELECT nama FROM pelanggan WHERE id NOT IN (SELECT pelanggan_id FROM pesanan)', 'Yang id-nya ga ada di daftar pelanggan_id = NOT IN.'),
      Q('Tampilkan <code>nama</code> dan <code>harga</code> produk yang harganya <b>di atas rata-rata</b> semua produk.', 'SELECT nama, harga FROM produk WHERE harga > (SELECT AVG(harga) FROM produk)', 'WHERE harga > (SELECT AVG(harga) FROM produk)', { umum: ['<code>WHERE harga &gt; AVG(harga)</code> langsung: error, agregat ga boleh di WHERE. Bungkus jadi subquery.'] }),
      Q('Tampilkan <code>nama</code> pelanggan yang <b>pernah punya pesanan batal</b>.', "SELECT nama FROM pelanggan WHERE id IN (SELECT pelanggan_id FROM pesanan WHERE status = 'batal')", "id IN (SELECT pelanggan_id FROM pesanan WHERE status = 'batal')"),
      Q('Tampilkan <code>nama</code> dan <code>harga</code> produk <b>paling mahal</b> pakai subquery MAX (bukan LIMIT).', 'SELECT nama, harga FROM produk WHERE harga = (SELECT MAX(harga) FROM produk)', 'WHERE harga = (SELECT MAX(harga) FROM produk)', { umum: ['Subquery yang ngembaliin banyak baris dibandingin pakai =: hasilnya salah. MAX bikin subquery ngembaliin satu nilai.'] }),
      P('Subquery di <code>WHERE harga &gt; (…)</code> harus ngembaliin...', [['Satu nilai', 'Dibandingin pakai >, jadi harus tepat satu angka.'], ['Banyak kolom', 'Ga bisa ngebandingin satu harga sama banyak kolom.'], ['Tabel kosong', 'Hasilnya ga ada yang lolos.'], ['Teks', 'Bisa aja teks, tapi intinya harus satu nilai.']], 'Kalau subquery ngembaliin daftar, pakai IN.'),
      RK('Kartu contekan subquery', [['WHERE x > (SELECT AVG(x) …)', 'bandingin sama satu nilai'], ['WHERE id IN (SELECT …)', 'ada di daftar'], ['WHERE id NOT IN (SELECT …)', 'ga ada di daftar'], ['FROM (SELECT …) AS t', 'tabel sementara'], ['Dikerjain duluan', 'query di dalam kurung']]),
    ]),

    L('cte', 'mahir', 'CTE: query bertahap pakai WITH', 10, [
      I('WITH = kolom bantu-nya SQL', '<p>Query panjang gampang bikin pusing. <b>CTE</b> (Common Table Expression) motong query jadi tahapan yang dikasih nama:</p><pre>WITH nilai_pesanan AS (\n  SELECT pesanan_id, SUM(qty) AS n\n  FROM item\n  GROUP BY pesanan_id\n)\nSELECT AVG(n) FROM nilai_pesanan</pre><p>Bagian WITH bikin tabel sementara <code>nilai_pesanan</code>. Query di bawahnya make tabel itu kayak tabel biasa. Mirip bikin kolom bantu di Excel sebelum ngitung hasil akhir.</p>'),
      I('Kapan pakai CTE', '<ul><li>Butuh <b>agregat dari agregat</b>: rata-rata dari total per pesanan, persen pelanggan yang belanja lebih dari sekali.</li><li>Query kepanjangan dan pengen kebaca per langkah.</li><li>Beberapa tahap: <code>WITH a AS (…), b AS (…) SELECT …</code>, dipisah koma, WITH-nya cukup sekali.</li></ul><p>CTE dan subquery di FROM sebenarnya setara. CTE lebih enak dibaca dan lebih disukai reviewer di tes kerja.</p>'),
      C('Rata-rata nilai belanja per pesanan (AOV)', '<b>Average Order Value</b> = rata-rata nilai rupiah satu pesanan. Metrik wajib di e-commerce.', [
        ['SELECT i.pesanan_id, SUM(i.qty * pr.harga) AS nilai\nFROM item i\nJOIN produk pr ON pr.id = i.produk_id\nGROUP BY i.pesanan_id', 'Tahap 1: hitung nilai tiap pesanan (qty × harga, dijumlah per pesanan). Satu baris per pesanan.'],
        ['WITH nilai_pesanan AS (\n  SELECT i.pesanan_id, SUM(i.qty * pr.harga) AS nilai\n  FROM item i\n  JOIN produk pr ON pr.id = i.produk_id\n  GROUP BY i.pesanan_id\n)\nSELECT ROUND(AVG(nilai), 0) AS aov\nFROM nilai_pesanan', 'Tahap 2: bungkus tahap 1 jadi CTE, terus rata-ratain. Ini agregat dari agregat, ga bisa ditulis dalam satu SELECT biasa.'],
      ]),
      QB('Lengkapin: pelanggan (pelanggan_id) yang punya <b>lebih dari 3 pesanan selesai</b>.', "WITH n AS (\n  SELECT pelanggan_id, COUNT(*) AS jumlah\n  FROM pesanan\n  WHERE status = 'selesai'\n  GROUP BY ___\n)\nSELECT pelanggan_id, jumlah\nFROM n\nWHERE jumlah ___ 3", "WITH n AS (SELECT pelanggan_id, COUNT(*) AS jumlah FROM pesanan WHERE status = 'selesai' GROUP BY pelanggan_id) SELECT pelanggan_id, jumlah FROM n WHERE jumlah > 3", 'Kelompoknya per pelanggan. Di query luar, jumlah udah jadi kolom biasa, jadi boleh pakai WHERE.'),
      Q('Hitung <b>total belanja</b> tiap pelanggan (nama, kolom <code>total</code>) dari pesanan berstatus <b>selesai</b>, ambil <b>3 terbesar</b>.', "WITH b AS (SELECT p.pelanggan_id, SUM(i.qty * pr.harga) AS total FROM pesanan p JOIN item i ON i.pesanan_id = p.id JOIN produk pr ON pr.id = i.produk_id WHERE p.status = 'selesai' GROUP BY p.pelanggan_id) SELECT c.nama, b.total FROM b JOIN pelanggan c ON c.id = b.pelanggan_id ORDER BY b.total DESC LIMIT 3", 'CTE total per pelanggan_id, terus JOIN ke pelanggan buat ambil nama, ORDER BY total DESC LIMIT 3.', { urut: true, umum: ["Lupa WHERE status = 'selesai': pesanan batal dan retur ikut kehitung jadi belanja."] }),
      Q('Hitung <b>rata-rata jumlah barang (qty) per pesanan</b>, ga usah dibulatin.', 'WITH q AS (SELECT pesanan_id, SUM(qty) AS n FROM item GROUP BY pesanan_id) SELECT AVG(n) FROM q', 'Total qty per pesanan dulu (CTE), baru AVG.', { umum: ['AVG(qty) langsung dari tabel item: itu rata-rata qty per <b>baris item</b>, bukan per pesanan. Satu pesanan bisa punya beberapa baris item.'] }),
      P('Kenapa <code>AVG(SUM(qty))</code> ga bisa ditulis langsung?', [['Agregat ga bisa dibungkus agregat lain di level yang sama, harus bertahap', 'Bikin tahap dulu (CTE/subquery), baru diagregat lagi.'], ['Karena AVG cuma buat harga', 'AVG bisa buat kolom angka apa aja.'], ['Bisa kok', 'SQLite dan DB lain nolak, "misuse of aggregate".'], ['Karena qty teks', 'qty itu angka.']], 'Agregat dari agregat = tanda butuh CTE.'),
      RK('Kartu contekan CTE', [['WITH t AS ( … ) SELECT … FROM t', 'tabel sementara bernama t'], ['WITH a AS (…), b AS (…)', 'beberapa tahap, WITH sekali'], ['Agregat dari agregat', 'AOV, rata-rata per pelanggan, repeat rate'], ['Query luar', 'kolom CTE udah kolom biasa, boleh WHERE']]),
    ]),

    L('tanggal', 'mahir', 'Tanggal: tren per bulan', 9, [
      I('Motong tanggal', "<p>Tanggal di sini teks berformat <code>YYYY-MM-DD</code>. Di SQLite:</p><ul><li><code>substr(tgl, 1, 7)</code> → <code>'2026-03'</code> (tahun-bulan)</li><li><code>strftime('%m', tgl)</code> → <code>'03'</code> (bulan)</li><li><code>strftime('%Y', tgl)</code> → <code>'2026'</code></li></ul><p>Di database lain fungsinya beda tapi konsepnya sama: MySQL <code>DATE_FORMAT</code> / <code>MONTH()</code>, PostgreSQL <code>DATE_TRUNC('month', tgl)</code>, BigQuery <code>FORMAT_DATE</code>.</p>"),
      I('Pola laporan tren', "<pre>SELECT substr(tgl, 1, 7) AS bulan, COUNT(*) AS jumlah\nFROM pesanan\nGROUP BY bulan\nORDER BY bulan</pre><p>Potong tanggal jadi bulan, kelompokin per bulan, urutin dari bulan awal. Format YYYY-MM bisa diurutin langsung karena tahunnya di depan.</p>"),
      C('Tren pendapatan per bulan', 'Atasan minta grafik pendapatan bulanan dari pesanan <b>selesai</b>.', [
        ["SELECT p.tgl, substr(p.tgl, 1, 7) AS bulan\nFROM pesanan p", 'Liat dulu hasil potongannya: tanggal lengkap jadi tahun-bulan.'],
        ["SELECT substr(p.tgl, 1, 7) AS bulan,\n  SUM(i.qty * pr.harga) AS pendapatan\nFROM pesanan p\nJOIN item i ON i.pesanan_id = p.id\nJOIN produk pr ON pr.id = i.produk_id\nWHERE p.status = 'selesai'\nGROUP BY bulan", 'Gabung ke item dan produk buat dapet rupiahnya, saring yang selesai, kelompokin per bulan.'],
        ["SELECT substr(p.tgl, 1, 7) AS bulan,\n  SUM(i.qty * pr.harga) AS pendapatan\nFROM pesanan p\nJOIN item i ON i.pesanan_id = p.id\nJOIN produk pr ON pr.id = i.produk_id\nWHERE p.status = 'selesai'\nGROUP BY bulan\nORDER BY bulan", 'Urutin dari bulan awal. Hasil ini siap dijadiin grafik garis di Excel atau Power BI.'],
      ]),
      QB('Lengkapin: jumlah pesanan <b>selesai</b> per bulan, urut dari bulan awal.', "SELECT substr(tgl, 1, 7) AS bulan, COUNT(*) AS jumlah\nFROM pesanan\nWHERE status = 'selesai'\nGROUP BY ___\nORDER BY ___", "SELECT substr(tgl, 1, 7) AS bulan, COUNT(*) AS jumlah FROM pesanan WHERE status = 'selesai' GROUP BY bulan ORDER BY bulan", 'Kelompokin dan urutin pakai alias bulan.', { urut: true }),
      Q('Hitung <b>jumlah pesanan per bulan</b> (pakai substr(tgl,1,7) sebagai <code>bulan</code>), urut dari bulan paling awal.', 'SELECT substr(tgl, 1, 7) AS bulan, COUNT(*) AS jumlah FROM pesanan GROUP BY bulan ORDER BY bulan', 'substr(tgl,1,7) AS bulan … GROUP BY bulan ORDER BY bulan', { urut: true }),
      Q('Total <b>pendapatan</b> (qty × harga) dari pesanan berstatus <b>selesai</b>, satu angka.', "SELECT SUM(i.qty * pr.harga) AS pendapatan FROM item i JOIN produk pr ON pr.id = i.produk_id JOIN pesanan ps ON ps.id = i.pesanan_id WHERE ps.status = 'selesai'", 'Gabungin item, produk, pesanan. Filter status selesai.'),
      Q('Berapa pelanggan yang <b>daftar di tahun 2026</b>?', "SELECT COUNT(*) FROM pelanggan WHERE strftime('%Y', tgl_daftar) = '2026'", "strftime('%Y', tgl_daftar) = '2026', atau tgl_daftar LIKE '2026%'.", { umum: ["Bandingin sama angka <code>= 2026</code> tanpa kutip: strftime ngembaliin teks, jadi ga sama."] }),
      P('Kenapa format tanggal <code>2026-03-15</code> enak buat diurutin?', [['Tahun di depan, jadi urutan teks = urutan waktu', 'Teks diurutin dari karakter kiri. Tahun dulu, bulan, tanggal.'], ['Karena pakai strip', 'Strip ga ngaruh.'], ['Karena SQL otomatis ngerti tanggal', 'Di SQLite ini cuma teks.'], ['Ga enak, harus diubah dulu', 'Justru format ini standar internasional (ISO 8601).']], 'Format 15-03-2026 bakal kacau kalau diurutin sebagai teks.'),
      RK('Kartu contekan tanggal', [['substr(tgl, 1, 7)', "'2026-03', tahun-bulan"], ["strftime('%m', tgl)", 'bulan saja'], ["strftime('%Y', tgl)", 'tahun saja'], ['GROUP BY bulan ORDER BY bulan', 'pola tren bulanan'], ['MySQL / PostgreSQL', 'DATE_FORMAT, MONTH() / DATE_TRUNC']]),
    ]),

    L('window', 'mahir', 'Window function: ranking dan total berjalan', 11, [
      I('Ngitung tanpa ngeringkas', "<p>GROUP BY ngeringkas banyak baris jadi satu. <b>Window function</b> ngitung juga, tapi <b>tiap baris tetap ada</b>.</p><pre>SELECT kategori, nama, harga,\n  RANK() OVER (PARTITION BY kategori ORDER BY harga DESC) AS r\nFROM produk</pre><ul><li><code>OVER (…)</code>: tanda window function.</li><li><code>PARTITION BY kategori</code>: hitungannya dimulai ulang tiap kategori (kayak GROUP BY tapi baris ga diringkas).</li><li><code>ORDER BY harga DESC</code>: urutan di dalam tiap partisi.</li></ul>"),
      I('Ranking dan running total', "<table class=\"tabel-mini\"><tr><th>fungsi</th><th>kalau ada harga seri</th></tr><tr><td><code>ROW_NUMBER()</code></td><td>1, 2, 3, 4 (selalu beda)</td></tr><tr><td><code>RANK()</code></td><td>1, 2, 2, 4 (loncat)</td></tr><tr><td><code>DENSE_RANK()</code></td><td>1, 2, 2, 3 (ga loncat)</td></tr></table><p><b>Running total</b> (total kumulatif): <code>SUM(n) OVER (ORDER BY bulan)</code>.</p><p>Window function ga boleh langsung di WHERE. Bungkus pakai subquery atau CTE, baru disaring.</p>"),
      C('Produk termahal di tiap kategori', 'Buat halaman "unggulan kategori", ambil 1 produk termahal dari tiap kategori.', [
        ['SELECT kategori, nama, harga,\n  RANK() OVER (ORDER BY harga DESC) AS r\nFROM produk', 'RANK tanpa PARTITION: ranking harga dari seluruh produk. Smartwatch nomor 1.'],
        ['SELECT kategori, nama, harga,\n  RANK() OVER (PARTITION BY kategori ORDER BY harga DESC) AS r\nFROM produk', 'Tambah PARTITION BY kategori. Ranking mulai dari 1 lagi di tiap kategori. Semua 20 baris tetap ada.'],
        ['SELECT kategori, nama, harga\nFROM (\n  SELECT kategori, nama, harga,\n    RANK() OVER (PARTITION BY kategori ORDER BY harga DESC) AS r\n  FROM produk\n)\nWHERE r = 1', 'Bungkus jadi subquery, baru saring r = 1. Dapet 5 baris, satu per kategori.'],
      ]),
      QB('Lengkapin: kasih nomor urut produk <b>dari termurah</b> di tiap kategori (kolom <code>no</code>).', 'SELECT kategori, nama, harga,\n  ROW_NUMBER() OVER (PARTITION BY ___ ORDER BY harga ___) AS no\nFROM produk', 'SELECT kategori, nama, harga, ROW_NUMBER() OVER (PARTITION BY kategori ORDER BY harga ASC) AS no FROM produk', 'Partisi per kategori, termurah = ASC.'),
      Q('Ambil <b>produk termahal di tiap kategori</b>: kategori, nama, harga.', 'SELECT kategori, nama, harga FROM (SELECT kategori, nama, harga, RANK() OVER (PARTITION BY kategori ORDER BY harga DESC) AS r FROM produk) WHERE r = 1', 'Bungkus RANK() di subquery, lalu WHERE r = 1.', { umum: ['Nulis <code>WHERE RANK() OVER (…) = 1</code> langsung: window function ga boleh di WHERE.'] }),
      Q('Tampilkan <code>bulan</code>, jumlah pesanan bulan itu (<code>n</code>), dan <b>total kumulatif</b>-nya (<code>kumulatif</code>), urut dari bulan awal.', 'WITH b AS (SELECT substr(tgl, 1, 7) AS bulan, COUNT(*) AS n FROM pesanan GROUP BY bulan) SELECT bulan, n, SUM(n) OVER (ORDER BY bulan) AS kumulatif FROM b ORDER BY bulan', 'CTE jumlah per bulan, terus SUM(n) OVER (ORDER BY bulan).', { urut: true }),
      P('Harga 500, 400, 400, 300. RANK() dari termahal ngasih...', [['1, 2, 2, 4', 'Yang seri dapet ranking sama, ranking berikutnya loncat.'], ['1, 2, 3, 4', 'Itu ROW_NUMBER.'], ['1, 2, 2, 3', 'Itu DENSE_RANK.'], ['1, 1, 1, 1', 'Cuma kalau semua harga sama.']], 'Hafalin bedanya tiga fungsi ranking, sering ditanya di tes SQL.'),
      RK('Kartu contekan window', [['f() OVER (…)', 'hitung per baris, baris ga diringkas'], ['PARTITION BY k', 'mulai ulang tiap k'], ['ROW_NUMBER / RANK / DENSE_RANK', '1234 / 1224 / 1223'], ['SUM(n) OVER (ORDER BY bulan)', 'total berjalan'], ['Saring hasil window', 'bungkus subquery/CTE dulu']]),
    ]),

    L('kasus', 'mahir', 'Studi kasus: soal SQL ala tes kerja', 12, [
      I('Cara ngadepin soal studi kasus', '<p>Tes SQL di rekrutmen data analyst biasanya berupa pertanyaan bisnis. Pakai urutan mikir ini:</p><ol><li><b>Pahami pertanyaannya.</b> Yang diminta angka apa? Per apa?</li><li><b>Cari tabelnya.</b> Kolom yang dibutuhin ada di tabel mana aja?</li><li><b>Tentuin "grain"-nya.</b> Hasil akhirnya satu baris per apa? (per kota, per bulan, satu angka)</li><li><b>Saring</b> yang ga relevan (status batal, tanggal di luar periode).</li><li><b>Hitung, urutin, batasi.</b></li><li><b>Cek kewajaran.</b> Total masuk akal? Ada yang dobel gara-gara JOIN?</li></ol>'),
      I('Metrik yang sering ditanya', '<table class="tabel-mini"><tr><th>metrik</th><th>rumus</th></tr><tr><td>Revenue / omzet</td><td>SUM(qty × harga) pesanan selesai</td></tr><tr><td>AOV</td><td>revenue ÷ jumlah pesanan</td></tr><tr><td>Cancel rate</td><td>pesanan batal ÷ semua pesanan</td></tr><tr><td>Repeat rate</td><td>pelanggan yang beli &gt; 1 kali ÷ pelanggan yang pernah beli</td></tr><tr><td>Top N</td><td>ORDER BY … DESC LIMIT N</td></tr></table><p class="tip">Buat persen, kali <code>100.0</code> (pakai titik nol) biar hasilnya desimal. <code>100 * 3 / 7</code> di SQL bisa kebulet jadi bilangan bulat.</p>'),
      C('Kota mana yang omzetnya paling besar?', 'Pertanyaan: <i>"Kota mana yang omzet pesanan selesainya paling besar? Kasih 3 teratas."</i>', [
        ['SELECT c.kota, p.id, p.status\nFROM pesanan p\nJOIN pelanggan c ON c.id = p.pelanggan_id', 'Tabel: kota ada di pelanggan, status di pesanan, rupiah dari item × produk. Mulai sambungin pesanan ke pelanggan.'],
        ["SELECT c.kota, i.qty * pr.harga AS nilai\nFROM pesanan p\nJOIN pelanggan c ON c.id = p.pelanggan_id\nJOIN item i ON i.pesanan_id = p.id\nJOIN produk pr ON pr.id = i.produk_id\nWHERE p.status = 'selesai'", 'Sambung ke item dan produk biar dapet nilai rupiah per baris item. Saring status selesai.'],
        ["SELECT c.kota, SUM(i.qty * pr.harga) AS omzet\nFROM pesanan p\nJOIN pelanggan c ON c.id = p.pelanggan_id\nJOIN item i ON i.pesanan_id = p.id\nJOIN produk pr ON pr.id = i.produk_id\nWHERE p.status = 'selesai'\nGROUP BY c.kota\nORDER BY omzet DESC\nLIMIT 3", 'Grain-nya per kota: GROUP BY kota, SUM nilainya, urut terbesar, ambil 3.'],
      ], { penutup: 'Pas interview, ceritain langkah ini sambil nulis. Rekruter nilai cara mikirnya, bukan cuma hasil akhirnya.' }),
      Q('<b>Top 3 produk</b> berdasarkan total qty terjual dari pesanan <b>selesai</b>: nama dan total qty (<code>terjual</code>). Kalau seri, urut nama A sampai Z.', "SELECT pr.nama, SUM(i.qty) AS terjual FROM item i JOIN pesanan p ON p.id = i.pesanan_id JOIN produk pr ON pr.id = i.produk_id WHERE p.status = 'selesai' GROUP BY pr.id, pr.nama ORDER BY terjual DESC, pr.nama LIMIT 3", 'item JOIN pesanan (buat status) JOIN produk (buat nama), GROUP BY produk.', { urut: true, umum: ['Lupa JOIN ke pesanan, jadi ga bisa nyaring status. Pesanan batal ikut kehitung.'] }),
      Q('Berapa <b>persen pesanan yang batal</b>? Bulatin 1 desimal.', "SELECT ROUND(100.0 * SUM(CASE WHEN status = 'batal' THEN 1 ELSE 0 END) / COUNT(*), 1) AS persen_batal FROM pesanan", "100.0 * SUM(CASE WHEN status = 'batal' THEN 1 ELSE 0 END) / COUNT(*)", { umum: ['Pakai 100 (bukan 100.0): pembagian bilangan bulat bikin desimalnya kebuang.', "WHERE status = 'batal' lalu COUNT(*)/COUNT(*): penyebutnya ikut kesaring, hasilnya 100%."] }),
      Q('Hitung <b>repeat rate</b> (persen, 1 desimal): dari pelanggan yang punya pesanan <b>selesai</b>, berapa persen yang punya lebih dari 1 pesanan selesai?', "WITH n AS (SELECT pelanggan_id, COUNT(*) AS k FROM pesanan WHERE status = 'selesai' GROUP BY pelanggan_id) SELECT ROUND(100.0 * SUM(CASE WHEN k > 1 THEN 1 ELSE 0 END) / COUNT(*), 1) FROM n", 'CTE jumlah pesanan selesai per pelanggan, terus hitung yang k > 1 dibagi semua.', { umum: ['Penyebutnya semua 30 pelanggan. Yang ditanya cuma pelanggan yang pernah punya pesanan selesai.'] }),
      Q('<b>Segmen</b> mana yang <b>rata-rata nilai pesanannya</b> (AOV, pesanan selesai) paling tinggi? Tampilkan segmen dan <code>aov</code> (ga usah dibulatin), urut terbesar.', "WITH v AS (SELECT p.id, c.segmen, SUM(i.qty * pr.harga) AS nilai FROM pesanan p JOIN pelanggan c ON c.id = p.pelanggan_id JOIN item i ON i.pesanan_id = p.id JOIN produk pr ON pr.id = i.produk_id WHERE p.status = 'selesai' GROUP BY p.id, c.segmen) SELECT segmen, AVG(nilai) AS aov FROM v GROUP BY segmen ORDER BY aov DESC", 'Tahap 1 (CTE): nilai tiap pesanan plus segmennya. Tahap 2: AVG per segmen.', { urut: true, umum: ['AVG(qty × harga) langsung per segmen: itu rata-rata per baris item, bukan per pesanan.'] }),
      RK('Kartu contekan studi kasus', [['1. Pertanyaan', 'angka apa, per apa'], ['2. Tabel', 'kolom ada di mana, JOIN lewat apa'], ['3. Grain', 'satu baris hasil = satu apa'], ['4. Saring', 'status, periode'], ['5. Hitung', 'SUM/COUNT/AVG, persen pakai 100.0'], ['6. Cek', 'angka masuk akal? JOIN bikin dobel?']], 'Latihan terbaik: bikin pertanyaan bisnismu sendiri dari database ini, terus jawab.'),
    ]),
  ]

  const tes = [
    T('dasar', 'Query buat ambil semua kolom dari tabel produk?', ['SELECT * FROM produk', 'GET produk', 'SELECT produk', 'SHOW * produk'], 'SELECT kolom FROM tabel. Tanda * artinya semua kolom.'),
    T('dasar', 'Buat nyaring baris (misal kota = Bandung) pakai?', ['WHERE', 'ORDER BY', 'GROUP BY', 'LIMIT'], 'WHERE nyaring baris. ORDER BY ngurutin, GROUP BY ngelompokin, LIMIT motong jumlah baris.'),
    T('dasar', "WHERE kategori = 'Elektronik' AND harga < 300000 ngambil produk yang...", ['Elektronik dan harganya di bawah 300 ribu', 'Elektronik atau harganya di bawah 300 ribu', 'Semua Elektronik', 'Error'], 'AND = dua syarat harus benar semua.'),
    T('menengah', 'Jumlah pelanggan di tiap kota. Bagian yang wajib ada?', ['GROUP BY kota', 'ORDER BY kota', 'WHERE kota', 'LIMIT kota'], '"Tiap kota" = satu baris per kota = GROUP BY kota, dengan COUNT(*) di SELECT.'),
    T('menengah', 'Nama pelanggan cuma ada di tabel pelanggan, pesanan cuma nyimpen pelanggan_id. Cara gabunginnya?', ['JOIN ... ON pelanggan.id = pesanan.pelanggan_id', 'UNION', 'GROUP BY', 'HAVING'], 'JOIN nyambungin baris dua tabel lewat kolom penghubung (foreign key).'),
    T('menengah', 'Mau nyaring kategori yang rata-rata harganya di atas 150 ribu. Syaratnya ditaruh di?', ['HAVING AVG(harga) > 150000', 'WHERE AVG(harga) > 150000', 'WHERE harga > 150000', 'ORDER BY AVG(harga)'], 'Nyaring hasil hitungan per kelompok = HAVING. WHERE ga bisa pakai agregat.'),
    T('mahir', 'Mau ranking produk termahal per kategori tanpa ngeringkas baris. Pakai?', ['RANK() OVER (PARTITION BY kategori ...)', 'GROUP BY kategori', 'HAVING', 'DISTINCT'], 'Window function ngitung per baris tanpa ngeringkas. PARTITION BY bikin ranking mulai ulang tiap kategori.'),
    T('mahir', 'Bedanya WHERE sama HAVING?', ['WHERE nyaring baris mentah, HAVING nyaring hasil GROUP BY', 'Sama aja', 'HAVING lebih cepat', 'WHERE cuma buat angka'], 'Urutan jalan: FROM, WHERE, GROUP BY, HAVING, SELECT. WHERE jalan sebelum ada hasil hitungan.'),
    T('mahir', 'Cari pelanggan yang belum pernah pesan. Paling tepat?', ['LEFT JOIN pesanan, lalu WHERE pesanan.id IS NULL', 'JOIN pesanan, lalu WHERE pesanan.id IS NULL', 'WHERE pesanan.id = NULL', 'GROUP BY pelanggan'], 'JOIN biasa udah ngebuang pelanggan tanpa pesanan. LEFT JOIN nyisain mereka dengan NULL, terus disaring pakai IS NULL.'),
  ]

  susun('SQ', pelajaran, tes)
})()
